// Bundle the Typst template (templates/typst/jote-article) into a TS module the converter app
// can put into its download zip, the way public/jote-article.ts carries the LaTeX class.
//
//   node apps/converter/scripts/bundle-typst-template.mjs
//
// Writes apps/converter/lib/generated/jote-article-typst.ts. Runs before `dev` and `build`
// (see package.json); the generated file is checked in so the app typechecks without it.
import { mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '../../..')
const templateDir = join(root, 'templates/typst/jote-article')
const out = join(root, 'apps/converter/lib/generated/jote-article-typst.ts')

const TEXT = /\.(typ|toml|md|svg|bib|txt)$/i
const SKIP = new Set(['example'])

function walk(dir) {
  return readdirSync(dir).flatMap((name) => {
    if (SKIP.has(name) || name.startsWith('.')) return []
    const path = join(dir, name)
    return statSync(path).isDirectory() ? walk(path) : [path]
  })
}

const entries = walk(templateDir)
  .sort()
  .map((path) => {
    const rel = relative(templateDir, path).split('\\').join('/')
    const data = readFileSync(path)
    return TEXT.test(path)
      ? `  ${JSON.stringify(rel)}: { text: ${JSON.stringify(data.toString('utf8'))} },`
      : `  ${JSON.stringify(rel)}: { base64: ${JSON.stringify(data.toString('base64'))} },`
  })

const source = `// Generated by apps/converter/scripts/bundle-typst-template.mjs from
// templates/typst/jote-article. Do not edit; re-run the script instead.
/* eslint-disable */

export type TemplateFile = { text: string } | { base64: string }

/** The \`jote-article\` Typst template, keyed by path inside the template directory. */
export const typstTemplateFiles: Record<string, TemplateFile> = {
${entries.join('\n')}
}
`

mkdirSync(dirname(out), { recursive: true })
let previous = ''
try {
  previous = readFileSync(out, 'utf8')
} catch {
  // first run
}
if (previous !== source) {
  writeFileSync(out, source)
  console.log(`wrote ${relative(root, out)} (${entries.length} files)`)
} else {
  console.log(`${relative(root, out)} is up to date`)
}
